<?php
namespace App\Http\Controllers\Admin;use App\Actions\TransitionServiceRequestAction;use App\Http\Controllers\Controller;use App\Models\ServiceRequest;use Illuminate\Http\Request;
class ServiceRequestController extends Controller{public function index(){return view('admin.requests.index',['requests'=>ServiceRequest::with(['service','room'])->latest()->paginate(40)]);}public function update(Request $request,ServiceRequest $serviceRequest,TransitionServiceRequestAction $action){$data=$request->validate(['status'=>['required','in:PENDING,ACCEPTED,ASSIGNED,IN_PROGRESS,COMPLETED,REJECTED,CANCELLED,ESCALATED'],'note'=>['nullable','string','max:1000']]);$action->execute($serviceRequest,$data['status'],$request->user()->id,$data['note']??null);return back()->with('status','Request status updated.');}}
